function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();

  // Sky
  brush.fill("#e0a58a"); // Sky blue
  brush.fillBleed(0.3);
  brush.beginShape();
  brush.vertex(0, 0); // Top left corner of the sky
  brush.vertex(400, 0); // Bottom right corner of the sky
  brush.vertex(400, 400); // Bottom right corner of the sky
  brush.vertex(0, 400); // Top left corner of the sky
  brush.endShape(true);

  // Hills
  brush.fill("#8fba85"); // Light green
  brush.fillTexture(0.3, 0.5); // Texture of hills
  brush.beginShape();
  brush.vertex(0, 100); // Top left corner of the hills
  brush.vertex(100, 100); // Bottom right corner of the hills
  brush.vertex(100, 300); // Bottom right corner of the hills
  brush.vertex(0, 300); // Top left corner of the hills
  brush.endShape(true);

  // Sun
  brush.fill("#d38545"); // Golden yellow
  brush.fillTexture(0.5, 0.8); // Texture of the sun
  brush.beginShape();
  brush.vertex(200, 100); // Position of the sun
  brush.vertex(250, 100); // Position of the sun
  brush.vertex(250, 50); // Position of the sun
  brush.vertex(200, 50); // Position of the sun
  brush.endShape(true);

  // Clouds
  brush.fill("#aaa9b0"); // Light gray clouds
  brush.fillTexture(0.4, 0.8); // Texture of the clouds
  brush.beginShape();
  brush.vertex(150, 100); // Position of the clouds
  brush.vertex(250, 100); // Position of the clouds
  brush.vertex(250, 300); // Position of the clouds
  brush.vertex(150, 300); // Position of the clouds
  brush.endShape(true);
}

