function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Hill structure
  brush.fill("#e0c58e", 50);
  brush.circle(0, 0, 100);
  brush.fill("#d6a97d", 50);
  brush.circle(180, 50, 150);
  brush.fill("#e0b38f", 50);
  brush.circle(0, 140, 120);

  // Mountain line and clouds
  brush.fill("#86c9e5", 80);
  brush.vertex(-30, -30);
  brush.vertex(30, -120);
  brush.vertex(60, -50);
  brush.vertex(75, 0);
  brush.endShape(true);

  brush.fill("#a9f5e9", 50);
  brush.vertex(0, -25);
  brush.vertex(0, -50);
  brush.vertex(25, -60);
  brush.vertex(50, -10);
  brush.endShape(true);

  // Sun and details
  brush.fill("#ffcc00", 95); // Red sun
  brush.circle(200, 30, 100);

  // Celestial elements
  brush.fill("#f0e68c", 70); // Sky
  brush.vertex(0, -400);
  brush.vertex(250, -350);
  brush.vertex(250, -300);
  brush.vertex(0, -250);
  brush.endShape(true);

  // Shade effects
  brush.fillTexture(0.5, 20); // Added_texture
  brush.fill(Texture, "Convex");
  brush.beginShape();
  brush.vertex(-20, -200);
  brush.vertex(-60, -190);
  brush.vertex(-90, -208);
  brush.vertex(-100, -230);
  brush.endShape(true);
  brush.fillTexture(1, 35); // Added_texture2
  brush.fill(Texture, "Convex");
  brush.beginShape();
  brush.vertex(-150, -150);
  brush.vertex(-170, -90);
  brush.vertex(-190, -50);
  brush.vertex(-180, -30);
  brush.endShape(true);
}

