function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Painting the hills
  brush.fill("#006400", 50); // Green hills
  brush.fillTexture(0.75, 1); // Add texture to the hills

  // Creating hills
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true); // Close the shape

  // Painting the sun
  brush.fill("#f86034", 80); // Orange-yellow sun
  brush.fillBleed(0.5); // Add some bleeds to the sun

  // Creating sun
  brush.beginShape();
  brush.vertex(200, 50); // Top of the sun
  brush.vertex(200, 100); // Middle of the sun
  brush.vertex(150, 150); // Bottom of the sun
  brush.vertex(250, 150); // Bottom of the sun
  brush.endShape(true); // Close the shape

  // Painting the sky
  brush.fill("#9C8D4E", 100); // Dark blue sky
  brush.fillTexture(0.5, 1); // Add some texture to the sky

  // Creating sky
  brush.beginShape();
  brush.vertex(0, 200); // Top of the sky
  brush.vertex(400, 200); // Middle of the sky
  brush.vertex(400, 250); // Bottom of the sky
  brush.vertex(0, 250); // Bottom of the sky
  brush.endShape(true); // Close the shape

  // Painting the grass
  brush.fill("#8B8B8B", 30); // Dark green grass
  brush.fillTexture(0.3, 1); // Add some texture to the grass

  // Creating grass
  brush.beginShape();
  brush.vertex(200, 100); // Top of the grass
  brush.vertex(200, 130); // Middle of the grass
  brush.vertex(230, 180); // Bottom of the grass
  brush.vertex(170, 180); // Bottom of the grass
  brush.endShape(true); // Close the shape
}

